import json, subprocess, warnings, os
warnings.filterwarnings("ignore")
from TTS.utils.synthesizer import Synthesizer
from hts_close import close_voice
lines = [
 "हमेशा थकान? चेहरा पीला? सांस फूलती है? बर्फ या मिट्टी खाने का मन करता है? हो सकता है आयरन कम हो. आज सोमवार की हेल्थ टिप में जानिए, आयरन स्टडीज़ और फेरिटिन टेस्ट. आखिर तक देखिए.",
 "आयरन से हीमोग्लोबिन बनता है, जो ऑक्सीजन पहुंचाता है. आयरन स्टडीज़ में चार जांच हैं. सीरम आयरन, अभी खून में आयरन. टी आई बी सी, आयरन ढोने वाली गाड़ियां. सैचुरेशन, कितनी गाड़ियां भरी हैं. और फेरिटिन, गोदाम में जमा आयरन.",
 "राष्ट्रीय परिवार स्वास्थ्य सर्वे पांच में, भारत की लगभग सत्तावन प्रतिशत महिलाओं, और सड़सठ प्रतिशत छोटे बच्चों में खून की कमी मिली. आयरन की कमी इसका एक आम कारण है. लक्षण, थकान, कमज़ोरी, पीली त्वचा, सांस फूलना, और तेज़ धड़कन.",
 "आयरन की कमी में आमतौर पर, फेरिटिन कम, आयरन कम, टी आई बी सी ज़्यादा, और सैचुरेशन कम. आयरन ज़्यादा जमा हो, तो फेरिटिन और सैचुरेशन ज़्यादा. ज़्यादा आयरन भी लिवर और दिल को नुकसान पहुंचा सकता है.",
 "किसे ज़रूरत हो सकती है? सी बी सी में खून की कमी. पीरियड्स में ज़्यादा ब्लीडिंग. प्रेग्नेंसी. कमज़ोर खान पान. बार बार ब्लड डोनेशन, या पेट की बीमारी. और बार बार खून चढ़ने पर, जैसे थैलेसीमिया में, कभी कभी एम आर आई भी.",
 "तैयारी. सीरम आयरन सुबह सबसे ज़्यादा होता है, इसलिए सुबह का सैंपल बेहतर. कई लैब लगभग आठ घंटे खाली पेट कहती हैं. सिर्फ फेरिटिन के लिए आमतौर पर ज़रूरी नहीं. आयरन की गोली या इंजेक्शन लेते हैं, तो डॉक्टर को पहले बताएं.",
 "विश्व स्वास्थ्य संगठन के अनुसार, पांच साल से ऊपर के स्वस्थ व्यक्ति में, फेरिटिन लगभग पंद्रह से कम, यानी आयरन की कमी. सैचुरेशन लगभग, पुरुषों में बीस से पचास, महिलाओं में पंद्रह से पैंतालीस प्रतिशत. रेंज हर लैब में अलग होती है.",
 "ध्यान दें, इंफेक्शन या सूजन में फेरिटिन बढ़ जाता है, तो आयरन कम होने पर भी नॉर्मल दिख सकता है. मिथक, हर खून की कमी आयरन की कमी है. सच, थैलेसीमिया ट्रेट में आयरन की ज़रूरत नहीं होती. पहले जांच, फिर डॉक्टर की सलाह.",
 close_voice("क्या आपने कभी फेरिटिन टेस्ट करवाया है?"),
]
d = os.environ.get("HTS_MODEL", "/tmp/hi/hi/")
s = Synthesizer(tts_checkpoint=d + "fastpitch/best_model.pth", tts_config_path=d + "fastpitch/config.json",
                vocoder_checkpoint=d + "hifigan/best_model.pth", vocoder_config=d + "hifigan/config.json", use_cuda=False)
durs = []
for i, l in enumerate(lines):
    f = f"/tmp/irnr_{i}.wav"; s.save_wav(s.tts(l, speaker_name="female"), f)
    subprocess.run(["ffmpeg","-nostdin","-y","-loglevel","error","-i",f,"-af","rubberband=pitch=0.96:formant=preserved,equalizer=f=250:t=q:w=1:g=2,treble=g=-1.5:f=6000",f"/tmp/irn_{i}.wav"],check=True); f=f"/tmp/irn_{i}.wav"
    durs.append(float(subprocess.check_output(["ffprobe", "-v", "error", "-show_entries", "format=duration", "-of", "csv=p=0", f]).decode()))
json.dump(durs, open("/tmp/irn_durs.json", "w")); print([round(x, 1) for x in durs], round(sum(durs), 1))
